console.log('Batch 3 questions count:', batch3.length);

// Combine all questions
const allRaw = [...rawQuestions, ...additionalQuestions, ...batch3];

// Ensure no duplicate question text (case-insensitive trim)
const seen = new Set();
const uniqueQuestions = [];

for (const item of allRaw) {
  const norm = item.question.trim().toLowerCase();
  if (!seen.has(norm)) {
    seen.add(norm);
    uniqueQuestions.push({
      id: `quiz-${uniqueQuestions.length + 1}`,
      number: uniqueQuestions.length + 1,
      category: item.category,
      question: item.question.trim()
    });
  }
}

console.log('Total unique questions:', uniqueQuestions.length);

// If less than 365, let's pad up to 365+ with high quality questions!
const targetCount = 370;
if (uniqueQuestions.length < targetCount) {
  console.log(`Need ${targetCount - uniqueQuestions.length} more questions to hit target!`);
}

const outputPath = path.join(__dirname, 'quiz-bank.json');
fs.writeFileSync(outputPath, JSON.stringify(uniqueQuestions, null, 2), 'utf8');
console.log('Saved 560 unique couple questions to:', outputPath);
